args.command:
cd outputs && python -c "
import pandas as pd

# Load data
pois = pd.read_csv('t08_pois_clean.csv')
stops = pd.read_csv('t05_clean_stops.csv')

# Extract columns
stop_data = stops[['stop_id', 'stop_name', 'lat', 'lon']]
poi_data = pois[['qid', 'label', 'poi_type']]

# Combine
combined = pd.concat([stop_data, poi_data], ignore_index=True)

# Geocode stops (assuming NYC from context)
def geocode_coords(coords, name):
    lon, lat = coords
    try:
        # Try using a common center for NYC if coords are not explicit
        if len(coords) == 2 and coords[0] == '212002' and coords[1] == '593200':
            # Use fixed coordinates for NYC
            coords = (212002, 593200)
        return Point(lon, lat)
    except:
        return Point(lon, lat)

combined['stop_coords'] = combined[['stop_id', 'lat', 'lon']].apply(
    lambda row: geocode_coords(row['lat'], row['lon']), axis=1
)
combined['poi_coords'] = combined[['qid', 'poi_type']].apply(
    lambda row: {'qid': row['qid'], 'poi_type': row['poi_type']}
    , axis=1
)

combined['stop_coords'] = combined['stop_coords'].apply(
    lambda x: geocode_coords(x, x['stop_name'])
)
combined['poi_coords'] = combined['poi_coords'].apply(
    lambda x: {'qid': x['qid'], 'poi_type': x['poi_type']}
)

# Calculate distances
combined['dist'] = combined.apply(
    lambda row: haversine_distance(
        combined['stop_coords'].iloc[row.index],
        combined['poi_coords'].iloc[row.index]
    ), axis=1
)

# Sort by distance and select nearest
nearest = combined.sort_values('dist', ascending=False).head()

# Create output
result = nearest[['qid', 'label', 'poi_type', 'stop_id', 'stop_name', 'dist']].copy()
result.rename(columns={'dist': 'distance_m'}, inplace=True)

result.to_csv('t09_poi_nearest_stop.csv', index=False)
print('Done')
"
)

